/bin/zsh -lc "rg --files -g AGENTS.md -g '"'!docs/**'"'; rg -n 'Harmaahaikara|19.11.2025' docs/paivakirjat/Kide/2025-11.txt; python3 - <<'PY'
import zipfile,xml.etree.ElementTree as E,glob
for f in glob.glob('docs/kiertokirjeet/*')+glob.glob('docs/liitteet/*'):
 print('\\nFILE',f)
 with zipfile.ZipFile(f) as z:
  if f.endswith('.docx'):
   r=E.fromstring(z.read('word/document.xml'))
   for p in r.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'):
    print(''.join(p.itertext()))
  else:
   for n in z.namelist():
    if n=='xl/sharedStrings.xml' or n=='xl/workbook.xml' or n.startswith('xl/worksheets/sheet'):
     print(n,z.read(n).decode())
PY"

